typedef struct {char base[128],root[256],state[256],path[512],database[512],engine[65],model[65],source[65];unsigned char wave[32044];char *job,*watch;size_t cycle;SourcesInferenceConfig inference;SourcesConfig cfg;} Fixture;
static char *call(Fixture *f,const char *request,int expected){char *body=NULL;size_t bytes=0;FILE *out=open_memstream(&body,&bytes);assert(out);int rc=sources_dispatch(&f->cfg,request,strlen(request),out);assert(!fclose(out));if(rc!=expected)fprintf(stderr,"unexpected response %s\n",body);assert(rc==expected);Json j;assert(json_parse(&j,body,bytes));return body;}
static char *field(const char *body,const char *key){Json j;assert(json_parse(&j,body,strlen(body)));char *value=json_string(&j,json_get(&j,0,key));assert(value);return value;}
static void put32(unsigned char *p,uint32_t value){for(unsigned i=0;i<4;i++)p[i]=(unsigned char)(value>>(8*i));}
static void write_wave(Fixture *f,unsigned value){f->wave[44]=(unsigned char)value;FILE *out=fopen(f->path,"wb");assert(out&&fwrite(f->wave,1,sizeof(f->wave),out)==sizeof(f->wave)&&!fclose(out));hash_bytes(f->wave,sizeof(f->wave),f->source);}
static void init(Fixture *f){
    memset(f,0,sizeof(*f));strcpy(f->base,"/tmp/samosa-index-audio-failure-XXXXXX");assert(mkdtemp(f->base));snprintf(f->root,sizeof(f->root),"%s/files",f->base);snprintf(f->state,sizeof(f->state),"%s/state",f->base);snprintf(f->path,sizeof(f->path),"%s/voice.wav",f->root);snprintf(f->database,sizeof(f->database),"%s/sources.sqlite3",f->state);assert(!mkdir(f->root,0700));
    memcpy(f->wave,"RIFF",4);put32(f->wave+4,sizeof(f->wave)-8);memcpy(f->wave+8,"WAVEfmt ",8);put32(f->wave+16,16);f->wave[20]=1;f->wave[22]=1;put32(f->wave+24,16000);put32(f->wave+28,32000);f->wave[32]=2;f->wave[34]=16;memcpy(f->wave+36,"data",4);put32(f->wave+40,sizeof(f->wave)-44);write_wave(f,0);
    memset(f->engine,'a',64);memset(f->model,'b',64);f->inference=(SourcesInferenceConfig){.provider_id="fixture",.engine_sha256=f->engine,.model_sha256=f->model};f->cfg=(SourcesConfig){.root=f->root,.state=f->state,.owner="audio-owner",.inference=&f->inference};
    char *body=call(f,"{\"contract_version\":1,\"op\":\"index_create\",\"path\":\"\",\"operation_id\":\"create\"}",0);f->job=field(body,"job_id");free(body);char request[768];snprintf(request,sizeof(request),"{\"contract_version\":1,\"op\":\"index_step\",\"job_id\":\"%s\",\"operation_id\":\"initial\",\"max_items\":1}",f->job);body=call(f,request,0);assert(strstr(body,"waiting_audio"));free(body);
    snprintf(request,sizeof(request),"{\"contract_version\":1,\"op\":\"locator_watch_create\",\"operation_id\":\"watch\",\"locators\":[{\"path\":\"voice.wav\",\"expected_version\":\"%s\"}]}",f->source);body=call(f,request,0);f->watch=field(body,"watch_id");free(body);
}
static void change(Fixture *f,unsigned value){write_wave(f,value);char request[512];snprintf(request,sizeof(request),"{\"contract_version\":1,\"op\":\"locator_watch_step\",\"watch_id\":\"%s\",\"expected_cycle\":%zu}",f->watch,f->cycle);char *body=call(f,request,0);free(body);f->cycle++;}
static char *reindex(Fixture *f,const char *operation,int expected){char request[512];snprintf(request,sizeof(request),"{\"contract_version\":1,\"op\":\"index_reindex_step\",\"job_id\":\"%s\",\"operation_id\":\"%s\",\"max_items\":1}",f->job,operation);return call(f,request,expected);}
static sqlite3_int64 scalar(sqlite3 *db,const char *query){sqlite3_stmt *stmt=NULL;assert(sqlite3_prepare_v2(db,query,-1,&stmt,NULL)==SQLITE_OK&&sqlite3_step(stmt)==SQLITE_ROW);sqlite3_int64 value=sqlite3_column_int64(stmt,0);assert(sqlite3_finalize(stmt)==SQLITE_OK);return value;}
static void counts(Fixture *f,int jobs,int history,int pending){sqlite3 *db=NULL;assert(sqlite3_open(f->database,&db)==SQLITE_OK);assert(scalar(db,"SELECT count(*) FROM audio_index_jobs")==jobs&&scalar(db,"SELECT count(*) FROM index_audio_history")==history&&scalar(db,"SELECT count(*) FROM index_pending")==pending);assert(sqlite3_close(db)==SQLITE_OK);}
static void current(Fixture *f,const char *source){sqlite3 *db=NULL;sqlite3_stmt *stmt=NULL;assert(sqlite3_open(f->database,&db)==SQLITE_OK&&sqlite3_prepare_v2(db,"SELECT source FROM index_audio",-1,&stmt,NULL)==SQLITE_OK&&sqlite3_step(stmt)==SQLITE_ROW);assert(!strcmp((const char*)sqlite3_column_text(stmt,0),source));sqlite3_finalize(stmt);assert(sqlite3_close(db)==SQLITE_OK);}
static pid_t worker(Fixture *f,const char *operation,const char *point,int expected,char release[512]){
    char marker[512];snprintf(marker,sizeof(marker),"%s/%s.marker",f->base,operation);snprintf(release,512,"%s/%s.release",f->base,operation);pid_t child=fork();assert(child>=0);if(!child){assert(!setenv(point,marker,1));if(!strcmp(point,"SAMOSA_REINDEX_TEST_PRECOMMIT_MARKER"))assert(!setenv("SAMOSA_REINDEX_TEST_PRECOMMIT_RELEASE",release,1));char *body=reindex(f,operation,expected);if(expected)assert(strstr(body,"stale_observation")||strstr(body,"stale_scope")||strstr(body,"cancelled")||strstr(body,"deadline_exceeded"));free(body);_exit(0);}
    int ready=0;for(int i=0;i<500;i++){if(!access(marker,F_OK)){ready=1;break;}struct timespec delay={0,10000000};nanosleep(&delay,NULL);}assert(ready);return child;
}
static void kill_worker(pid_t child){assert(!kill(child,SIGKILL));int status;assert(waitpid(child,&status,0)==child&&WIFSIGNALED(status)&&WTERMSIG(status)==SIGKILL);}
static void release_worker(pid_t child,const char *release){FILE *out=fopen(release,"w");assert(out&&fputs("release",out)>=0&&!fclose(out));int status;assert(waitpid(child,&status,0)==child&&WIFEXITED(status)&&!WEXITSTATUS(status));}
static void failures(void){
    Fixture f;init(&f);char old[65];memcpy(old,f.source,65);change(&f,1);char release[512];pid_t child=worker(&f,"killed-admission","SAMOSA_AUDIO_REINDEX_TEST_ADMITTED_MARKER",0,release);counts(&f,1,0,1);current(&f,old);kill_worker(child);counts(&f,1,0,1);current(&f,old);
    char *body=reindex(&f,"killed-admission",0);assert(strstr(body,"interrupted"));free(body);body=reindex(&f,"resume-admission",0);assert(strstr(body,"\"reindexed_items\":1"));free(body);counts(&f,2,1,0);current(&f,f.source);
    change(&f,2);child=worker(&f,"killed-commit","SAMOSA_REINDEX_TEST_COMMITTED_MARKER",0,release);counts(&f,3,2,0);kill_worker(child);body=reindex(&f,"killed-commit",0);assert(strstr(body,"interrupted"));free(body);body=reindex(&f,"resume-commit",0);assert(strstr(body,"\"reindexed_items\":0"));free(body);counts(&f,3,2,0);
    memcpy(old,f.source,65);change(&f,3);child=worker(&f,"superseded-observation","SAMOSA_REINDEX_TEST_PRECOMMIT_MARKER",1,release);change(&f,4);release_worker(child,release);counts(&f,3,2,1);current(&f,old);body=reindex(&f,"latest-observation",0);assert(strstr(body,"\"reindexed_items\":1"));free(body);counts(&f,4,3,0);
    memcpy(old,f.source,65);change(&f,5);child=worker(&f,"replaced-root","SAMOSA_REINDEX_TEST_PRECOMMIT_MARKER",1,release);char moved[512];snprintf(moved,sizeof(moved),"%s/previous-root",f.base);assert(!rename(f.root,moved)&&!mkdir(f.root,0700));write_wave(&f,5);release_worker(child,release);counts(&f,4,3,1);current(&f,old);assert(!unlink(f.path)&&!rmdir(f.root)&&!rename(moved,f.root));body=reindex(&f,"restored-root",0);free(body);counts(&f,5,4,0);
    for(unsigned value=6;value<=8;value++){change(&f,value);char operation[32];snprintf(operation,sizeof(operation),"fill-%u",value);body=reindex(&f,operation,0);free(body);}counts(&f,8,7,0);memcpy(old,f.source,65);change(&f,9);body=reindex(&f,"queue-full",1);assert(strstr(body,"audio_index_limit"));free(body);counts(&f,8,7,1);current(&f,old);
    free(f.job);free(f.watch);
}
static int cancelled(void *path){return !access(path,F_OK);}
static double monotonic(void){struct timespec now;assert(!clock_gettime(CLOCK_MONOTONIC,&now));return (double)now.tv_sec+now.tv_nsec/1e9;}
static void controls(void){
    Fixture f;init(&f);char old[65],flag[512],release[512];memcpy(old,f.source,65);change(&f,1);snprintf(flag,sizeof(flag),"%s/cancel",f.base);f.cfg.cancelled=cancelled;f.cfg.cancellation=flag;pid_t child=worker(&f,"cancel-before-commit","SAMOSA_REINDEX_TEST_PRECOMMIT_MARKER",1,release);FILE *out=fopen(flag,"w");assert(out&&!fclose(out));release_worker(child,release);counts(&f,1,0,1);current(&f,old);f.cfg.cancelled=NULL;f.cfg.cancellation=NULL;char *body=reindex(&f,"resume-cancel",0);free(body);counts(&f,2,1,0);
    memcpy(old,f.source,65);change(&f,2);f.cfg.deadline_monotonic=monotonic()+1;child=worker(&f,"deadline-before-commit","SAMOSA_REINDEX_TEST_PRECOMMIT_MARKER",1,release);while(monotonic()<=f.cfg.deadline_monotonic){struct timespec delay={0,10000000};nanosleep(&delay,NULL);}release_worker(child,release);counts(&f,2,1,1);current(&f,old);f.cfg.deadline_monotonic=0;body=reindex(&f,"resume-deadline",0);free(body);counts(&f,3,2,0);free(f.job);free(f.watch);
}
static void history_capacity(void){Fixture f;init(&f);for(unsigned transition=0;transition<256;transition++){change(&f,(transition&1)?0:1);char operation[32];snprintf(operation,sizeof(operation),"history-%u",transition);char *body=reindex(&f,operation,0);assert(strstr(body,"\"reindexed_items\":1"));free(body);}counts(&f,2,256,0);size_t after=0,seen=0;for(size_t page=0;page<16;page++){char request[512];snprintf(request,sizeof(request),"{\"contract_version\":1,\"op\":\"index_audio_history\",\"job_id\":\"%s\",\"after\":%zu}",f.job,after);char *result=call(&f,request,0);Json j;size_t count,next;assert(json_parse(&j,result,strlen(result))&&json_uint(&j,json_get(&j,0,"returned_artifacts"),&count)&&count==16&&json_uint(&j,json_get(&j,0,"next_after"),&next)&&next>after);after=next;seen+=count;assert(strstr(result,page==15?"\"has_more\":false":"\"has_more\":true"));free(result);}assert(seen==256);char search_request[512];snprintf(search_request,sizeof(search_request),"{\"contract_version\":1,\"op\":\"index_audio_search\",\"job_id\":\"%s\",\"query\":\"transcript\"}",f.job);char *search=call(&f,search_request,0);assert(strstr(search,"\"scanned_captures\":0")&&strstr(search,"\"uncaptured_windows\":2")&&strstr(search,"\"returned_candidates\":0"));free(search);char previous[65];memcpy(previous,f.source,65);change(&f,1);char *body=reindex(&f,"history-full",1);assert(strstr(body,"index_limit"));free(body);counts(&f,2,256,1);current(&f,previous);free(f.job);free(f.watch);}
int main(void){failures();controls();history_capacity();puts("PASS audio reindex failure/history: actual SIGKILL inside admission and after commit, observation/root races, cancellation/deadline rollback, eight-job refusal, 256 real retained transitions, stable duplicate jobs and unchanged pending/current state at capacity");return 0;}
